// @plan build-my-plan  @planName Build My Plan  @pre src/plan-builder.js
/* Build My Plan (app users). The plan itself is generated by src/plan-builder.js from the client's answers.
   No answers yet → the questionnaire opens. Answers are saved in S.build and sync with the client's email + PIN. */
var MGB_COACH='https://www.macro.golf/match-up-session'; /* where "Speak to a coach" goes: change any time */
var MGB_KEY='mg-plan-build-my-plan-v1';
MGBuild.tools({x:x,MAX:MAX});
var MGB_SAVED=(function(){try{var st=JSON.parse(localStorage.getItem(MGB_KEY)||'{}')||{};return st.build&&st.build.answers?st.build.answers:null}catch(e){return null}})();
var MGB_PLAN=MGBuild.generate(MGB_SAVED||MGBuild.DEFAULTS,{x:x,MAX:MAX});
var CLIENT=MGB_PLAN.client,SESSIONS=MGB_PLAN.sessions;
CLIENT.coachUrl=MGB_COACH;
CLIENT.onRebuild=function(){mgbOpen(true)};
function mgbOpen(edit){
  MGBuild.open({answers:edit?MGB_SAVED:null,coachUrl:MGB_COACH,onCancel:edit?function(){}:null,onDone:function(a){
    var had=Object.keys(S.finished||{}).length>0||Object.keys(S.logs||{}).length>0;
    /* a new plan starts again at week 1; old sessions are kept in S.archive (habits, check-ins and weigh-ins carry on) */
    if(MGB_SAVED&&had){S.archive=S.archive||[];S.archive.push({answers:MGB_SAVED,logs:S.logs,finished:S.finished,choice:S.choice,ended:todayIso()});S.logs={};S.finished={};S.choice={};S.mgsDone={}}
    if(!MGB_SAVED||had){S.start=todayIso();S._wset=false;S.week=1}
    S.day=0;S.build={answers:a,created:todayIso()};S.tab='today';save();
    setTimeout(function(){location.reload()},400)}});
}
if(!MGB_SAVED)setTimeout(function(){mgbOpen(false)},0);
